document.addEventListener("DOMContentLoaded",()=>{const e={facts:[["Location","Kasaragod, Kerala","Bekal Fort stands on Kerala's northern coastline with scenic Arabian Sea views."],["Known for","Kerala's largest fort","The issue highlights Bekal as Kerala's largest fort and a major coastal heritage site."],["Builder focus","Shivappa Nayaka of Keladi","Bekal Fort is commonly associated with Shivappa Nayaka of the Keladi / Ikkeri Nayaka line."],["Fort type","Coastal defence fort","Its sea-facing walls, bastions and observation points explain its coastal military purpose."],["Signature feature","Observation tower","The fort is known for its prominent observation tower and sweeping sea views."],["Explorer focus","Coastal fortifications","This page covers overview, history, builder, fortifications, architecture, tower, facts and gallery."]],history:[["Coastal defence identity","Bekal Fort developed as a strategic coastal fort overlooking the Arabian Sea."],["Regional power story","The fort is linked with regional rulers and the coastal defence history of northern Kerala."],["Trade-route watchpoint","Its location helped monitor movement along the coast and sea-facing approaches."],["Heritage today","Today, Bekal is visited for fort walls, sea views, pathways, observation tower and coastal heritage."]],builder:[["Shivappa Nayaka","The fort is commonly connected with Shivappa Nayaka, a ruler known for strengthening fortifications."],["Keladi / Ikkeri Nayaka context","The builder story places Bekal within regional power struggles and coastal defence needs."],["Military planners","The layout shows practical planning for surveillance, movement, bastions and sea-facing defence."],["Local craftsmanship","Laterite stonework and coastal adaptation give the fort a distinct Kerala character."]],fortifications:[["Sea-facing walls","Massive walls face the Arabian Sea, turning the coastline into part of the defence system."],["Bastions","Rounded and projecting defensive points improved watch and control over approaches."],["Moat and entry control","Controlled entrances and protective barriers helped defend the fort from landward attacks."],["Elevated watchpoints","Height and visibility were essential for spotting movement along the coast."]],architecture:[["Laterite stone character","The fort's reddish laterite stone gives it a strong regional architectural identity."],["Keyhole-like plan","Bekal is often recognised for its distinctive plan shaped by the coastal landform."],["Ramps and pathways","Internal paths and ramps helped movement of people, guards and supplies."],["Open sea-edge layout","The architecture blends open sky, sea cliffs, walls and observation points."]],tower:[["Observation tower","The tower provides panoramic views and explains why surveillance mattered in a coastal fort."],["Sea watch","From elevated points, guards could monitor the Arabian Sea and nearby coastline."],["Visitor viewpoint","Today, the tower experience connects history with scenic photography and learning."],["Strategic visibility","The tower links architecture, defence and landscape into one clear visitor story."]],points:[["entry","Fort entrance",40,70,"Entry control","Controlled entry points slowed movement and protected the fort interior."],["wall","Sea-facing wall",56,58,"Coastal defence","Walls facing the Arabian Sea show the fort's coastal military purpose."],["tower","Observation tower",50,42,"Watchpoint","The tower gives panoramic views and explains surveillance strategy."],["bastion","Coastal bastion",68,48,"Fortification","Projecting defensive points improved visibility and control."],["sea","Arabian Sea viewpoint",64,28,"Scenic view","Sea views are central to Bekal's visitor identity."],["path","Internal pathways",34,50,"Architecture","Paths and ramps connect gates, walls, tower and open spaces."]],gallery:[["Coastal fort walls","../../assets/heritage_forts.png","Visual placeholder for Bekal's sea-facing defensive walls."],["Arabian Sea view","../../assets/travel_beaches.png","Coastal scenery and sea views are central to the Bekal experience."],["Observation tower","../../assets/heritage_monuments.png","The observation tower explains surveillance and panoramic visibility."],["Kerala heritage route","../../assets/hero_banner.png","Bekal Fort is presented as a coastal heritage explorer."]],interesting:[["Largest fort in Kerala","The issue specifically highlights Bekal as Kerala's largest fort."],["Sea and defence together","Bekal shows how coastlines could become part of military architecture."],["Observation tower story","The tower turns a scenic viewpoint into a lesson in surveillance and strategy."],["Laterite identity","The local stone texture makes the fort visually different from many inland forts."]],faqs:[["What is Bekal Fort famous for?","It is famous as Kerala's largest fort, with coastal defences and Arabian Sea views."],["Who is associated with building Bekal Fort?","Bekal Fort is commonly associated with Shivappa Nayaka of the Keladi / Ikkeri Nayaka line."],["What makes it a coastal fort?","Its sea-facing walls, bastions, watchpoints and location overlooking the Arabian Sea."],["What is the observation tower for?","It helped with surveillance and now serves as a major panoramic viewpoint."],["What does this explorer cover?","Overview, history, builder, coastal fortifications, architecture, tower, facts, gallery and landing integration."]]},a=e=>String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;"),t=e=>document.getElementById(e);function i(e,t,i){return`<article class="${t}"><span>0${i+1}</span><h3>${a(e[0])}</h3><p>${a(e[1])}</p></article>`}function r(i){const r=e.points.find(e=>e[0]===i)||e.points[0];document.querySelectorAll(".map-pin").forEach(e=>e.classList.toggle("active",e.dataset.point===r[0])),t("map-info").innerHTML=`<span>${a(r[4])}</span><h3>${a(r[1])}</h3><p>${a(r[5])}</p>`}t("facts-grid").innerHTML=e.facts.map(e=>`<article class="fact-card"><span>${a(e[0])}</span><strong>${a(e[1])}</strong><p>${a(e[2])}</p></article>`).join(""),t("history-grid").innerHTML=e.history.map((e,a)=>i(e,"history-card",a)).join(""),t("builder-grid").innerHTML=e.builder.map((e,a)=>i(e,"builder-card",a)).join(""),t("fortification-grid").innerHTML=e.fortifications.map((e,a)=>i(e,"fortification-card",a)).join(""),t("architecture-grid").innerHTML=e.architecture.map((e,a)=>i(e,"architecture-card",a)).join(""),t("tower-grid").innerHTML=e.tower.map((e,a)=>i(e,"tower-card",a)).join(""),t("interesting-grid").innerHTML=e.interesting.map((e,a)=>i(e,"interesting-card",a)).join(""),t("faq-list").innerHTML=e.faqs.map(e=>`<details class="faq-item"><summary>${a(e[0])}</summary><p>${a(e[1])}</p></details>`).join(""),t("map-pins").innerHTML=e.points.map((e,t)=>`<button class="map-pin" type="button" data-point="${a(e[0])}" style="left:${e[2]}%;top:${e[3]}%" aria-label="${a(e[1])}">${t+1}</button>`).join(""),document.querySelectorAll(".map-pin").forEach(e=>e.addEventListener("click",()=>r(e.dataset.point))),t("gallery-grid").innerHTML=e.gallery.map(e=>`<article class="gallery-card"><img src="${a(e[1])}" alt="${a(e[0])}" onerror="this.src='../../assets/hero_banner.png'"><div><h3>${a(e[0])}</h3><p>${a(e[2])}</p></div></article>`).join(""),r(e.points[0][0]),window.BekalFortExplorer={facts:()=>[...e.facts],points:()=>[...e.points],faqs:()=>[...e.faqs]}});